inner = {"src": "10.8.0.21", "dst": "10.10.20.5", "data": "GET /portal"}  # 안쪽 패킷을 딕셔너리로 만든다. VPN 주소 10.8.0.21 에서 회사 업무 포털 서버 10.10.20.5 로 가는 원래 패킷이다
outer = {"src": "211.36.10.7", "dst": "203.0.113.1", "data": inner}       # 바깥 패킷을 만든다. 집 공인 IP 에서 회사 VPN 게이트웨이로 가는 새 헤더를 씌우고, data 칸에 안쪽 패킷을 통째로 넣는다
print("중간 라우터가 보는 도착지:", outer["dst"])                         # 바깥 헤더의 도착지를 출력한다. 중간 라우터는 이 값만 보고 패킷을 보낸다
print("data 칸:", outer["data"])                                          # 바깥 패킷의 data 칸에 무엇이 들었는지 출력한다
print("안쪽 도착지:", outer["data"]["dst"])                               # data 칸이 딕셔너리이므로 그 안의 dst 를 한 번 더 꺼내 출력한다
